		if !r.Has(1) {
			return s, false
		}
		s.Packing = r.Get8()
		if s.Packing == 0 {
			return s, true
		}
		if s.Packing == 1 && k != 10 {
			n, ok := r.Leb()
			if !ok || n > uint64(s.Bits) {
				return s, false
			}
			s.Bits = int64(n)
			if k >= 18 {
				if !r.Has(16) {
					return s, false
				}
				s.Base = [2]uint64{r.Get64(), r.Get64()}
			} else {
				base, ok := r.Leb()
				if !ok {
					return s, false
				}
				if k >= 2 && k <= 5 {
					base = uint64(int64(base>>1) ^ -int64(base&1))
				}
				s.Base[0] = base
			}
			return s, true
		}
