func TableStatLoadMessages(values []TableStat, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !TableStatLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// TableMixedReset restores TableMixed's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func TableMixedReset(value *TableMixed) {
	value.ProtocolMagic = 0
	value.Sequence = 0
	value.AckSequence = 0
	value.AckBits = 0
	value.SessionId = 0
	value.ClientId = 0
	value.Nonce = 1
	value.WorldTime = 0
	value.FrameTick = 0
	value.ServerTime = 0.0
	for i := range value.Entities {
		TableEntityReset(&value.Entities[i])
	}
	value.EntitiesCount = 0
	for i := range value.Stats {
		TableStatReset(&value.Stats[i])
	}
	value.StatsCount = 0
	value.GameEvent.Type = TableEventTypeNone
	clear(value.Loadout[:])
	clear(value.PlayerName[:])
	value.PlayerNameLength = 0
	clear(value.Payload[:])
	value.PayloadLength = 0
	value.AimX = 0.0
	value.AimY = 0.0
	value.AimZ = 0.0
	value.Recoil = 0.0
	value.Drift = 0.0
	value.WideKey = 0
	value.Flux = 0
	value.Ping = 0.0
	value.CrcHint = 0
	value.HasExtra = false
	value.Extra = 0
	value.IdleTicks = 0
}

